function hashPassword(p:string,s:string){return crypto.scryptSync(p,s,64).toString('hex');}function makePassword(p:string){const salt=crypto.randomBytes(16).toString('hex');return{salt,hash:hashPassword(p,salt)}}function verifyPassword(p:string,h:string,s:string){const a=Buffer.from(hashPassword(p,s),'hex'),b=Buffer.from(h,'hex');return a.length===b.length&&crypto.timingSafeEqual(a,b)}function clean(v:string,max=3900){return v.length>max?v.slice(0,max-30)+'\n…truncated':v}function getGame(n:string){return db.prepare('SELECT * FROM games WHERE name=? COLLATE NOCASE').get(n) as any}function getTournament(n:string){return db.prepare('SELECT t.*,g.name game_name FROM tournaments t LEFT JOIN games g ON g.id=t.game_id WHERE t.name=? COLLATE NOCASE').get(n) as any}function getTournamentById(id:number){return db.prepare('SELECT t.*,g.name game_name FROM tournaments t LEFT JOIN games g ON g.id=t.game_id WHERE t.id=?').get(id) as any}function getPlayer(n:string){return db.prepare('SELECT * FROM players WHERE name=? COLLATE NOCASE').get(n) as any}function ensurePlayer(n:string,d?:string|null){const name=n.trim();if(!name)throw new Error('Player name cannot be empty.');let p=getPlayer(name);if(!p){const r=db.prepare('INSERT INTO players(name,discord_id) VALUES(?,?)').run(name,d??null);p={id:Number(r.lastInsertRowid),name,discord_id:d??null}}else if(d&&p.discord_id!==d){db.prepare('UPDATE players SET discord_id=? WHERE id=?').run(d,p.id);p.discord_id=d}return p}function addParticipant(t:number,p:number,seed?:number){db.prepare('INSERT OR IGNORE INTO tournament_players(tournament_id,player_id,seed) VALUES(?,?,?)').run(t,p,seed??null)}function isManager(i:{member:any}){return Boolean(i.member?.permissions?.has?.('ManageGuild')||i.member?.permissions?.has?.('Administrator'))}function parseResults(raw:string){const e=raw.split(',').map(x=>x.trim()).filter(Boolean).map((x,index)=>{const m=x.match(/^(?:(\d+)\s*:\s*)?(.+?)\s*=\s*(-?\d+(?:\.\d+)?)$/);return m?{position:m[1]?Number(m[1]):null,name:m[2].trim(),points:Number(m[3]),inputOrder:index}:null});if(!e.length||e.some(x=>!x||!x.name||!Number.isFinite(x.points)))return null;const v=e as {position:number|null,name:string,points:number,inputOrder:number}[],s=[...v].sort((a,b)=>b.points-a.points||a.inputOrder-b.inputOrder);return v.map(x=>({...x,position:x.position??s.findIndex(y=>y===x)+1}))}
