async function registerCommands(){const rest=new REST({version:'10'}).setToken(token!);await rest.put(Routes.applicationGuildCommands(clientId!,guildId!),{body:commands});console.log(`Registered ${commands.length} slash commands.`)}const client=new Client({intents:[GatewayIntentBits.Guilds]});
function managerPanel(){const rows=db.prepare('SELECT t.id,t.name,g.name game_name,t.status FROM tournaments t LEFT JOIN games g ON g.id=t.game_id ORDER BY t.created_at DESC LIMIT 25').all() as any[];if(!rows.length)return{content:'❌ No tournaments found. Create one with `/tournament`.'};const menu=new StringSelectMenuBuilder().setCustomId('tgs:tournament-select').setPlaceholder('Select a tournament').addOptions(rows.map(t=>({label:t.name.slice(0,100),value:String(t.id),description:`${t.game_name||'General'} • ${t.status}`.slice(0,100)})));return{content:'🏆 **TGS Tournament Manager**\nSelect a tournament to manage it.',components:[new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(menu)]}}
function managerButtons(id:number){return new ActionRowBuilder<ButtonBuilder>().addComponents(new ButtonBuilder().setCustomId(`tgs:update:${id}`).setLabel('Update').setStyle(ButtonStyle.Primary),new ButtonBuilder().setCustomId(`tgs:delete:${id}`).setLabel('Delete').setStyle(ButtonStyle.Danger),new ButtonBuilder().setCustomId(`tgs:fixtures:${id}`).setLabel('Create Fixtures').setStyle(ButtonStyle.Success),new ButtonBuilder().setCustomId(`tgs:report:${id}`).setLabel('Report').setStyle(ButtonStyle.Secondary))}function passwordModal(action:string,id:number){const m=new ModalBuilder().setCustomId(`tgs:password:${action}:${id}`).setTitle(`${action==='delete'?'Delete':action==='fixtures'?'Create Fixtures':'Update'} Tournament`);m.addComponents(new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('password').setLabel('Tournament password').setStyle(TextInputStyle.Short).setRequired(true).setMinLength(4)));return m}async function passwordOk(i:ModalSubmitInteraction,id:number){const t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return null}const p=i.fields.getTextInputValue('password');if(!t.password_hash||!t.password_salt||!verifyPassword(p,t.password_hash,t.password_salt)){await i.reply({content:'❌ Incorrect tournament password.',ephemeral:true});return null}return t}
function roundName(totalSlots:number,round:number){const totalRounds=Math.log2(totalSlots),fromFinal=totalRounds-round;if(fromFinal===0)return'Final';if(fromFinal===1)return'Semifinal';if(fromFinal===2)return'Quarterfinal';return`Round of ${totalSlots/(2**round)}`}function createFixtures(tournamentId:number){const players=db.prepare('SELECT p.id,p.name,tp.seed FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY CASE WHEN tp.seed IS NULL THEN 1 ELSE 0 END,tp.seed,p.name').all(tournamentId) as any[];if(players.length<2)throw new Error('At least 2 tournament players are required.');db.prepare('DELETE FROM matches WHERE tournament_id=?').run(tournamentId);const size=2**Math.ceil(Math.log2(players.length)),slots=[...players];while(slots.length<size)slots.push(null as any);const tx=db.transaction(()=>{for(let n=0;n<size;n+=2){const a=slots[n],b=slots[n+1],winner=a&&!b?a:!a&&b?b:null,status=winner?'bye':'pending';db.prepare('INSERT INTO matches(tournament_id,round_no,round_name,match_no,player1_id,player2_id,winner_id,status) VALUES(?,?,?,?,?,?,?,?)').run(tournamentId,1,roundName(size,1),n/2+1,a?.id??null,b?.id??null,winner?.id??null,status)}const rounds=Math.log2(size);for(let round=2;round<=rounds;round++){const count=size/(2**round);for(let m=1;m<=count;m++)db.prepare('INSERT INTO matches(tournament_id,round_no,round_name,match_no,status) VALUES(?,?,?,?,?)').run(tournamentId,round,roundName(size,round),m,'pending')}db.prepare("UPDATE tournaments SET status='fixtures_created',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(tournamentId)});tx();return{players:players.length,size}}function fixtureText(tournamentId:number){const rows=db.prepare('SELECT m.round_no,m.round_name,m.match_no,p1.name player1,p2.name player2,w.name winner,m.score1,m.score2,m.status FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? ORDER BY m.round_no,m.match_no').all(tournamentId) as any[];if(!rows.length)return'No fixtures.';return rows.map(m=>`**${m.round_name} ${m.match_no}** — ${m.player1||'TBD'} ${m.score1??''} vs ${m.score2??''} ${m.player2||'TBD'} • ${m.status==='completed'?`Winner: **${m.winner}**`:m.status==='bye'?`Bye: **${m.winner}`:'Pending'}`).join('\n')}function autoAdvanceRound(tournamentId:number,round:number){const matches=db.prepare('SELECT * FROM matches WHERE tournament_id=? AND round_no=? ORDER BY match_no').all(tournamentId,round) as any[];if(matches.some(m=>m.status==='pending'))return null;const next=round+1,nextMatches=db.prepare('SELECT * FROM matches WHERE tournament_id=? AND round_no=? ORDER BY match_no').all(tournamentId,next) as any[];if(!nextMatches.length){db.prepare("UPDATE tournaments SET status='completed',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(tournamentId);return{final:true}}const winners=matches.map(m=>m.winner_id).filter(Boolean),tx=db.transaction(()=>{for(let i=0;i<nextMatches.length;i++){const a=winners[i*2]??null,b=winners[i*2+1]??null,winner=a&&!b?a:!a&&b?b:null,status=winner?'bye':'pending';if(!a&&!b)continue;db.prepare('UPDATE matches SET player1_id=?,player2_id=?,winner_id=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(a,b,winner,status,nextMatches[i].id)}});tx();return{final:false}}
function xmlEscape(v:any){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}function excelAttachment(filename:string,sheets:{name:string,rows:any[]}[]){const rowsXml=(rows:any[])=>{const data=rows.length?rows:[{}],headers=Array.from(new Set(data.flatMap(r=>Object.keys(r||{}))));const head='<Row>'+headers.map(h=>`<Cell ss:StyleID="Header"><Data ss:Type="String">${xmlEscape(h)}</Data></Cell>`).join('')+'</Row>';const body=data.map(r=>'<Row>'+headers.map(h=>{const v=r?.[h],type=typeof v==='number'&&Number.isFinite(v)?'Number':'String';return`<Cell><Data ss:Type="${type}">${xmlEscape(v??'')}</Data></Cell>`}).join('')+'</Row>').join('');return head+body};const xml=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Header"><Font ss:Bold="1"/></Style></Styles>${sheets.map(sh=>`<Worksheet ss:Name="${xmlEscape(sh.name.slice(0,31))}"><Table>${rowsXml(sh.rows)}</Table></Worksheet>`).join('')}</Workbook>`;return new AttachmentBuilder(Buffer.from(xml,'utf8'),{name:filename})}function safeFileName(v:string){return String(v).replace(/[^a-z0-9_-]+/gi,'_').slice(0,80)||'report'}
function tournamentExcel(t:any){const participants=db.prepare("SELECT p.name player,COALESCE(tp.seed,'') seed,tp.joined_at joined_at FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY tp.seed IS NULL,tp.seed,p.name").all(t.id) as any[],races=db.prepare('SELECT ra.race_no race,ra.track,g.name game_name,ra.created_at FROM races ra JOIN tournaments tt ON tt.id=ra.tournament_id LEFT JOIN games g ON g.id=tt.game_id WHERE ra.tournament_id=? ORDER BY ra.race_no').all(t.id) as any[],results=db.prepare('SELECT ra.race_no race,ra.track,p.name player,r.position,r.points,r.kd,r.created_at recorded_at FROM results r JOIN races ra ON ra.id=r.race_id JOIN players p ON p.id=r.player_id WHERE ra.tournament_id=? ORDER BY ra.race_no,r.position,p.name').all(t.id) as any[],matches=db.prepare('SELECT m.round_no round,m.round_name,m.match_no match,p1.name player1,p2.name player2,m.score1,m.score2,w.name winner,m.status,m.updated_at FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? ORDER BY m.round_no,m.match_no').all(t.id) as any[];return excelAttachment(`TGS-${safeFileName(t.name)}-Report.xls`,[{name:'Summary',rows:[{Tournament:t.name,Game:t.game_name||'General',Status:t.status,Participants:participants.length,Races:races.length,Matches:matches.length}]},{name:'Participants',rows:participants},{name:'Races',rows:races},{name:'Race Results',rows:results},{name:'Matches',rows:matches}])}
function playerExcel(p:any,game?:string|null){const rp=game?[p.id,game]:[p.id],races=db.prepare(`SELECT t.name tournament,g.name game_name,ra.race_no race,ra.track,r.position,r.points,r.kd,ra.created_at recorded_at FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments t ON t.id=ra.tournament_id LEFT JOIN games g ON g.id=t.game_id WHERE r.player_id=? ${game?'AND g.name=? COLLATE NOCASE':''} ORDER BY ra.created_at DESC,ra.race_no DESC`).all(...rp) as any[],mp=game?[p.id,p.id,game]:[p.id,p.id],matches=db.prepare(`SELECT t.name tournament,g.name game_name,m.round_no round,m.round_name,m.match_no match,p1.name player1,p2.name player2,m.score1,m.score2,w.name winner,m.status,m.updated_at FROM matches m JOIN tournaments t ON t.id=m.tournament_id LEFT JOIN games g ON g.id=t.game_id LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE (m.player1_id=? OR m.player2_id=?) ${game?'AND g.name=? COLLATE NOCASE':''} ORDER BY m.updated_at DESC,m.round_no DESC,m.match_no DESC`).all(...mp) as any[],wins=matches.filter(m=>m.winner===p.name).length,losses=matches.filter(m=>m.status==='completed'&&m.winner&&m.winner!==p.name).length,total=races.reduce((sum,r)=>sum+Number(r.points||0),0);return excelAttachment(`TGS-${safeFileName(p.name)}-Report.xls`,[{name:'Summary',rows:[{Player:p.name,Game:game||'All Games',TotalRacePoints:total,Races:races.length,Matches:matches.length,MatchWins:wins,MatchLosses:losses}]},{name:'Race History',rows:races},{name:'Match History',rows:matches}])}
function gameExcel(g:any){const tournaments=db.prepare('SELECT t.name tournament,t.status,COUNT(DISTINCT ra.id) races,COUNT(DISTINCT m.id) matches FROM tournaments t LEFT JOIN races ra ON ra.tournament_id=t.id LEFT JOIN matches m ON m.tournament_id=t.id WHERE t.game_id=? GROUP BY t.id ORDER BY t.created_at DESC').all(g.id) as any[],players=db.prepare('SELECT p.name player,COALESCE((SELECT SUM(r.points) FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments tt ON tt.id=ra.tournament_id WHERE r.player_id=p.id AND tt.game_id=?),0) points,(SELECT COUNT(*) FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments tt ON tt.id=ra.tournament_id WHERE r.player_id=p.id AND tt.game_id=?) races,(SELECT COUNT(*) FROM matches m JOIN tournaments tt ON tt.id=m.tournament_id WHERE (m.player1_id=p.id OR m.player2_id=p.id) AND tt.game_id=?) matches,(SELECT COUNT(*) FROM matches m JOIN tournaments tt ON tt.id=m.tournament_id WHERE m.winner_id=p.id AND tt.game_id=?) match_wins FROM players p WHERE EXISTS(SELECT 1 FROM matches m JOIN tournaments tt ON tt.id=m.tournament_id WHERE (m.player1_id=p.id OR m.player2_id=p.id) AND tt.game_id=?) OR EXISTS(SELECT 1 FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments tt ON tt.id=ra.tournament_id WHERE r.player_id=p.id AND tt.game_id=?) ORDER BY points DESC,p.name').all(g.id,g.id,g.id,g.id,g.id,g.id) as any[],matches=db.prepare('SELECT t.name tournament,m.round_no round,m.round_name,m.match_no match,p1.name player1,p2.name player2,m.score1,m.score2,w.name winner,m.status,m.updated_at FROM matches m JOIN tournaments t ON t.id=m.tournament_id LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE t.game_id=? ORDER BY t.created_at DESC,m.round_no,m.match_no').all(g.id) as any[];return excelAttachment(`TGS-${safeFileName(g.name)}-Game-Report.xls`,[{name:'Summary',rows:[{Game:g.name,Tournaments:tournaments.length,Players:players.length,Matches:matches.length}]},{name:'Tournaments',rows:tournaments},{name:'Players',rows:players},{name:'Matches',rows:matches}])}
async function tournamentReport(i:ChatInputCommandInteraction|ButtonInteraction,name:string){const t=getTournament(name);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}const rows=db.prepare(`SELECT p.name,SUM(r.points) total,COUNT(r.id) races,MIN(r.position) best_position,AVG(r.position) avg_position FROM results r JOIN players p ON p.id=r.player_id JOIN races ra ON ra.id=r.race_id WHERE ra.tournament_id=? GROUP BY p.id ORDER BY total DESC,best_position ASC`).all(t.id) as any[],parts=db.prepare('SELECT p.name FROM tournament_players tp JOIN players p ON p.id=tp.player_id WHERE tp.tournament_id=? ORDER BY p.name').all(t.id) as any[],matches=db.prepare(`SELECT m.round_no,m.round_name,m.match_no,p1.name player1,p2.name player2,w.name winner,m.score1,m.score2,m.status FROM matches m LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE m.tournament_id=? ORDER BY m.round_no,m.match_no`).all(t.id) as any[],standings=rows.length?rows.map((r,n)=>`${n+1}. **${r.name}** — **${r.total} pts** • ${r.races} races • Best P${r.best_position??'-'} • Avg P${Number(r.avg_position||0).toFixed(1)}`).join('\n'):'No race results recorded.',pList=parts.length?parts.map(r=>`• ${r.name}`).join('\n'):'No participants.',matchList=matches.length?matches.map(m=>`⚔️ **${m.round_name} ${m.match_no}** — ${m.player1||'TBD'} ${m.score1??'-'} vs ${m.score2??'-'} ${m.player2||'TBD'} • ${m.status==='completed'?`Winner: **${m.winner||'TBD'}**`:m.status==='bye'?`Bye: **${m.winner||'TBD'}**`:'Pending'}`).join('\n'):'No fixtures recorded.';await i.reply({embeds:[new EmbedBuilder().setTitle(`🏆 ${t.name}`).setDescription(clean(`🎮 **Game:** ${t.game_name||'General'}\n📌 **Status:** ${t.status}\n\n**PARTICIPANTS**\n${pList}\n\n**POINT STANDINGS**\n${standings}\n\n**FIXTURE RESULTS**\n${matchList}`))],files:[tournamentExcel(t)]})}
async function handleCommand(i:ChatInputCommandInteraction){if(i.commandName==='notification-role'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const sub=i.options.getSubcommand();const mappings=loadNotificationMappings();if(sub==='add'){const emoji=i.options.getString('emoji',true).trim();const role=i.options.getRole('role',true);const message=(i.options.getString('message')||'').trim();if(!COMMON_EMOJIS.includes(emoji)&&emoji.length>0){/* custom unicode/server emoji accepted */}const me=i.guild?.members.me||await i.guild?.members.fetchMe().catch(()=>null);if(me&&role.position>=me.roles.highest.position){await i.reply({content:'❌ Move the bot role above '+roleMention(role.id)+' before using it.',ephemeral:true});return}const next=mappings.filter(m=>m.emoji!==emoji&&m.roleId!==role.id);next.push({emoji,roleId:role.id,message});saveNotificationMappings(next.slice(-20));await i.reply({content:'✅ '+emoji+' → '+roleMention(role.id)+' configured.',ephemeral:true});return}if(sub==='remove'){const emoji=i.options.getString('emoji',true).trim();saveNotificationMappings(mappings.filter(m=>m.emoji!==emoji));await i.reply({content:'✅ Removed mapping for '+emoji+'.',ephemeral:true});return}await i.reply({content:'🔔 '+(mappings.length?mappings.map(m=>m.emoji+' → '+roleMention(m.roleId)).join('\n'):'No mappings configured.'),ephemeral:true});return}if(i.commandName==='notification-panel'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}await i.reply(notificationPanel());return}if(i.commandName==='help'){await i.reply('**TGS Game Tracker**\n\n🎮 `/game`\n🏆 `/tournament`\n🛠️ `/tournament-manage`\n👥 `/tournament-player add/remove`\n👤 `/player`\n🏁 `/race`\n⚔️ `/match-result`\n📋 `/fixtures`\n📊 `/tournaments` `/players`\n📈 `/tournament-report` `/player-report` `/player-history` `/game-report`\n🎂 `/birthday set/remove/channel/list`');return}if(i.commandName==='game'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const name=i.options.getString('name',true).trim();try{db.prepare('INSERT INTO games(name) VALUES(?)').run(name);await i.reply(`✅ Game **${name}** created.`)}catch{await i.reply('❌ Game already exists.')}return}if(i.commandName==='tournament'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const name=i.options.getString('name',true).trim(),gameName=i.options.getString('game',true).trim(),password=i.options.getString('password',true),confirm=i.options.getString('confirm_password',true);if(password!==confirm){await i.reply('❌ Passwords do not match.');return}const g=getGame(gameName);if(!g){await i.reply('❌ Game not found. Create it with `/game`.');return}const hp=makePassword(password);try{db.prepare('INSERT INTO tournaments(name,game_id,password_hash,password_salt,status,created_by) VALUES(?,?,?,?,?,?)').run(name,g.id,hp.hash,hp.salt,'draft',i.user.id);await i.reply(`🏆 Tournament **${name}** created for **${g.name}**. Password protection enabled.`)}catch{await i.reply('❌ Tournament already exists.')}return}if(i.commandName==='tournament-manage'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}await i.reply(managerPanel());return}if(i.commandName==='tournament-player'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const sub=i.options.getSubcommand(),t=getTournament(i.options.getString('tournament',true));if(!t){await i.reply('❌ Tournament not found.');return}const p=ensurePlayer(i.options.getString('player',true),i.options.getUser('discord')?.id);if(sub==='add'){addParticipant(t.id,p.id);await i.reply(`✅ **${p.name}** added to **${t.name}**.`)}else{db.prepare('DELETE FROM tournament_players WHERE tournament_id=? AND player_id=?').run(t.id,p.id);await i.reply(`✅ **${p.name}** removed from **${t.name}**.`)}return}if(i.commandName==='player'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const p=ensurePlayer(i.options.getString('name',true),i.options.getUser('discord')?.id);await i.reply(`✅ Player **${p.name}** registered/linked.`);return}if(i.commandName==='race'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const t=getTournament(i.options.getString('tournament',true));if(!t){await i.reply('❌ Tournament not found.');return}const number=i.options.getInteger('number',true),track=i.options.getString('track',true),parsed=parseResults(i.options.getString('results',true));if(!parsed){await i.reply('❌ Invalid results format. Use Player=points,Player=points.');return}const tx=db.transaction(()=>{let race=db.prepare('SELECT * FROM races WHERE tournament_id=? AND race_no=?').get(t.id,number) as any;if(!race){const r=db.prepare('INSERT INTO races(tournament_id,race_no,track) VALUES(?,?,?)').run(t.id,number,track);race={id:Number(r.lastInsertRowid)}}else db.prepare('UPDATE races SET track=? WHERE id=?').run(track,race.id);db.prepare('DELETE FROM results WHERE race_id=?').run(race.id);for(const e of parsed){const p=ensurePlayer(e.name);addParticipant(t.id,p.id);db.prepare('INSERT INTO results(race_id,player_id,points,position) VALUES(?,?,?,?)').run(race.id,p.id,e.points,e.position)}});try{tx();await i.reply(`✅ Race ${number} recorded for **${t.name}**.`)}catch{await i.reply('❌ Could not save race results.')}return}if(i.commandName==='match-result'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const t=getTournament(i.options.getString('tournament',true));if(!t){await i.reply('❌ Tournament not found.');return}const round=i.options.getInteger('round',true),match=i.options.getInteger('match',true),winnerName=i.options.getString('winner',true),score1=i.options.getNumber('score1',true),score2=i.options.getNumber('score2',true),m=db.prepare('SELECT * FROM matches WHERE tournament_id=? AND round_no=? AND match_no=?').get(t.id,round,match) as any;if(!m){await i.reply('❌ Fixture not found.');return}if(m.status!=='pending'){await i.reply('❌ This fixture is already resolved.');return}const winner=getPlayer(winnerName);if(!winner||![m.player1_id,m.player2_id].includes(winner.id)){await i.reply('❌ Winner must be one of the two fixture players.');return}if(score1===score2){await i.reply('❌ Scores cannot be tied for a single-winner fixture.');return}const expected=score1>score2?m.player1_id:m.player2_id;if(winner.id!==expected){await i.reply('❌ Winner does not match the higher score.');return}db.prepare("UPDATE matches SET winner_id=?,score1=?,score2=?,status='completed',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(winner.id,score1,score2,m.id);const advanced=autoAdvanceRound(t.id,round);await i.reply(`✅ Match **R${round} M${match}** recorded. Winner: **${winner.name}**.${advanced?.final?' 🏆 Tournament completed!':''}`);return}if(i.commandName==='fixtures'){const t=getTournament(i.options.getString('tournament',true));if(!t){await i.reply('❌ Tournament not found.');return}await i.reply({embeds:[new EmbedBuilder().setTitle(`📋 ${t.name} Fixtures`).setDescription(clean(fixtureText(t.id)))]});return}if(i.commandName==='tournaments'){const game=i.options.getString('game');const rows=game?db.prepare('SELECT t.name,g.name game_name,t.status FROM tournaments t JOIN games g ON g.id=t.game_id WHERE g.name=? COLLATE NOCASE ORDER BY t.created_at DESC').all(game) as any[]:db.prepare('SELECT t.name,g.name game_name,t.status FROM tournaments t LEFT JOIN games g ON g.id=t.game_id ORDER BY t.created_at DESC').all() as any[];await i.reply({embeds:[new EmbedBuilder().setTitle(game?`🏆 ${game} Tournaments`:'🏆 All Tournaments').setDescription(clean(rows.length?rows.map((r,n)=>`${n+1}. **${r.name}** — 🎮 ${r.game_name||'General'} • ${r.status}`).join('\n'):'No tournaments found.'))]});return}if(i.commandName==='players'){const rows=db.prepare('SELECT name,discord_id FROM players ORDER BY name').all() as any[];await i.reply({embeds:[new EmbedBuilder().setTitle('👥 TGS Players').setDescription(clean(rows.length?rows.map((r,n)=>`${n+1}. **${r.name}** — ${r.discord_id?`<@${r.discord_id}>`:'No Discord link'}`).join('\n'):'No players registered.'))]});return}if(i.commandName==='tournament-report'){await tournamentReport(i,i.options.getString('tournament',true));return}if(i.commandName==='player-report'||i.commandName==='player-history'){const p=getPlayer(i.options.getString('player',true));if(!p){await i.reply('❌ Player not found.');return}const game=i.options.getString('game'),rp=game?[p.id,game]:[p.id],mp=game?[p.id,p.id,game]:[p.id,p.id],races=db.prepare(`SELECT t.name tournament,g.name game_name,ra.race_no,ra.track,r.points,r.position FROM results r JOIN races ra ON ra.id=r.race_id JOIN tournaments t ON t.id=ra.tournament_id LEFT JOIN games g ON g.id=t.game_id WHERE r.player_id=? ${game?'AND g.name=? COLLATE NOCASE':''} ORDER BY ra.created_at DESC,ra.race_no DESC`).all(...rp) as any[],matches=db.prepare(`SELECT t.name tournament,g.name game_name,m.round_no,m.round_name,m.match_no,p1.name player1,p2.name player2,m.score1,m.score2,w.name winner,m.status FROM matches m JOIN tournaments t ON t.id=m.tournament_id LEFT JOIN games g ON g.id=t.game_id LEFT JOIN players p1 ON p1.id=m.player1_id LEFT JOIN players p2 ON p2.id=m.player2_id LEFT JOIN players w ON w.id=m.winner_id WHERE (m.player1_id=? OR m.player2_id=?) ${game?'AND g.name=? COLLATE NOCASE':''} ORDER BY m.updated_at DESC,m.round_no DESC,m.match_no DESC`).all(...mp) as any[],total=races.reduce((sum,r)=>sum+Number(r.points||0),0),wins=matches.filter(m=>m.winner===p.name).length,losses=matches.filter(m=>m.status==='completed'&&m.winner&&m.winner!==p.name).length;if(i.commandName==='player-history'){const lines=[...races.map(r=>`🏁 **${r.game_name||'General'}** • ${r.tournament} • Race ${r.race_no} • ${r.track} — **P${r.position??'-'} / ${r.points} pts**`),...matches.map(m=>`⚔️ **${m.game_name||'General'}** • ${m.tournament} • ${m.round_name} ${m.match_no} — ${m.player1||'TBD'} ${m.score1??'-'} vs ${m.score2??'-'} ${m.player2||'TBD'} • ${m.status==='completed'?`Winner: **${m.winner||'TBD'}**`:m.status==='bye'?`Bye: **${m.winner||'TBD'}**`:'Pending'}`)];await i.reply({embeds:[new EmbedBuilder().setTitle(`📋 ${p.name} History`).setDescription(clean(lines.length?lines.join('\n'):'No race or match records found.'))],files:[playerExcel(p,game)]});return}await i.reply({embeds:[new EmbedBuilder().setTitle(`📊 ${p.name} Report`).setDescription(clean(`**Total Race Points:** ${total}\n**Race Records:** ${races.length}\n**Match Records:** ${matches.length}\n**Match Wins:** ${wins}\n**Match Losses:** ${losses}\n**Tournaments:** ${new Set([...races.map(r=>r.tournament),...matches.map(m=>m.tournament)]).size}`))],files:[playerExcel(p,game)]});return}if(i.commandName==='game-report'){const g=getGame(i.options.getString('game',true));if(!g){await i.reply('❌ Game not found.');return}const ts=db.prepare('SELECT t.name,COUNT(DISTINCT ra.id) races FROM tournaments t LEFT JOIN races ra ON ra.tournament_id=t.id WHERE t.game_id=? GROUP BY t.id ORDER BY t.created_at DESC').all(g.id) as any[],ps=db.prepare('SELECT p.name,SUM(r.points) points,COUNT(r.id) races FROM results r JOIN players p ON p.id=r.player_id JOIN races ra ON ra.id=r.race_id JOIN tournaments t ON t.id=ra.tournament_id WHERE t.game_id=? GROUP BY p.id ORDER BY points DESC').all(g.id) as any[];await i.reply({embeds:[new EmbedBuilder().setTitle(`🎮 ${g.name} Report`).setDescription(clean(`**Tournaments**\n${ts.length?ts.map((r,n)=>`${n+1}. **${r.name}** — ${r.races} races`).join('\n'):'None'}\n\n**Players**\n${ps.length?ps.map((r,n)=>`${n+1}. **${r.name}** — ${r.points} pts • ${r.races} races`).join('\n'):'None'}`))],files:[gameExcel(g)]});return}if(i.commandName==='birthday'){const sub=i.options.getSubcommand();if(sub==='set'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const u=i.options.getUser('user',true),month=i.options.getInteger('month',true),day=i.options.getInteger('day',true);db.prepare('INSERT INTO birthdays(discord_id,month,day,enabled,updated_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(discord_id) DO UPDATE SET month=excluded.month,day=excluded.day,enabled=1,updated_at=CURRENT_TIMESTAMP').run(u.id,month,day,1);await i.reply(`🎂 Birthday saved for **${u.username}**: ${day}/${month}.`);return}if(sub==='remove'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const u=i.options.getUser('user',true);db.prepare('DELETE FROM birthdays WHERE discord_id=?').run(u.id);await i.reply(`🗑️ Birthday removed for **${u.username}**.`);return}if(sub==='channel'){if(!isManager(i)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const c=i.options.getChannel('channel',true);db.prepare('INSERT INTO birthday_config(guild_id,channel_id,enabled,updated_at) VALUES(?,?,1,CURRENT_TIMESTAMP) ON CONFLICT(guild_id) DO UPDATE SET channel_id=excluded.channel_id,enabled=1,updated_at=CURRENT_TIMESTAMP').run(guildId,c.id);await i.reply(`🎂 Birthday announcement channel set to <#${c.id}>.`);return}const rows=db.prepare('SELECT discord_id,month,day,enabled FROM birthdays ORDER BY month,day').all() as any[];await i.reply({embeds:[new EmbedBuilder().setTitle('🎂 Birthday List').setDescription(clean(rows.length?rows.map(r=>`<@${r.discord_id}> — ${r.day}/${r.month} ${r.enabled?'':'(disabled)'}`).join('\n'):'No birthdays configured.'))]});return}}
function updateModal(t:any){const m=new ModalBuilder().setCustomId(`tgs:update-form:${t.id}`).setTitle('Update Tournament');m.addComponents(new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('password').setLabel('Tournament password').setStyle(TextInputStyle.Short).setRequired(true).setMinLength(4)),new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('name').setLabel('Tournament name').setStyle(TextInputStyle.Short).setRequired(true).setValue(t.name)),new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('game').setLabel('Game name').setStyle(TextInputStyle.Short).setRequired(true).setValue(t.game_name||'General')),new ActionRowBuilder<TextInputBuilder>().addComponents(new TextInputBuilder().setCustomId('status').setLabel('Status: draft/live/completed').setStyle(TextInputStyle.Short).setRequired(true).setValue(t.status)));return m}async function handleButton(i:ButtonInteraction){const [prefix,action,idText]=i.customId.split(':');if(prefix!=='tgs')return;if(!isManager(i as any)){await i.reply({content:'❌ Manager permission required.',ephemeral:true});return}const id=Number(idText),t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}if(action==='report'){await tournamentReport(i,t.name);return}if(action==='update'){await i.showModal(updateModal(t));return}if(action==='delete'||action==='fixtures')await i.showModal(passwordModal(action,id))}async function handlePasswordModal(i:ModalSubmitInteraction){const parts=i.customId.split(':'),action=parts[2],id=Number(parts[3]),t=await passwordOk(i,id);if(!t)return;if(action==='delete'){db.prepare('DELETE FROM tournaments WHERE id=?').run(id);await i.reply({content:`🗑️ Tournament **${t.name}** deleted.`,ephemeral:true});return}if(action==='fixtures'){try{const r=createFixtures(id);await i.reply({content:`✅ Fixtures created for **${t.name}**.\n👥 Players: ${r.players}\n📐 Bracket size: ${r.size}\n\nUse /fixtures to view them.`,ephemeral:true})}catch(e:any){await i.reply({content:`❌ ${e?.message||'Could not create fixtures.'}`,ephemeral:true})}}}async function handleUpdateForm(i:ModalSubmitInteraction){const id=Number(i.customId.split(':')[2]),t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}const p=i.fields.getTextInputValue('password');if(!t.password_hash||!t.password_salt||!verifyPassword(p,t.password_hash,t.password_salt)){await i.reply({content:'❌ Incorrect tournament password.',ephemeral:true});return}const name=i.fields.getTextInputValue('name').trim(),gameName=i.fields.getTextInputValue('game').trim(),status=i.fields.getTextInputValue('status').trim().toLowerCase();if(!name){await i.reply({content:'❌ Tournament name cannot be empty.',ephemeral:true});return}const g=getGame(gameName);if(!g){await i.reply({content:`❌ Game **${gameName}** not found.`,ephemeral:true});return}if(!['draft','live','completed','fixtures_created'].includes(status)){await i.reply({content:'❌ Invalid status.',ephemeral:true});return}try{db.prepare('UPDATE tournaments SET name=?,game_id=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(name,g.id,status,id);await i.reply({content:`✅ Tournament updated to **${name}** • 🎮 ${g.name} • ${status}`,ephemeral:true})}catch{await i.reply({content:'❌ Could not update tournament. The name may already exist.',ephemeral:true})}}async function handleSelect(i:StringSelectMenuInteraction){if(i.customId!=='tgs:tournament-select')return;const id=Number(i.values[0]),t=getTournamentById(id);if(!t){await i.reply({content:'❌ Tournament not found.',ephemeral:true});return}await i.reply({content:`🏆 **${t.name}**\n🎮 ${t.game_name||'General'}\n📌 Status: ${t.status}`,components:[managerButtons(id)],ephemeral:true})}
client.on('interactionCreate',async(i:Interaction)=>{try{if(i.commandName==='notification-role'&&focused.name==='emoji'){const configured=loadNotificationMappings().map(m=>m.emoji);const choices=[...new Set([...COMMON_EMOJIS,...configured])].filter(e=>e.toLowerCase().includes(query.toLowerCase())).slice(0,25);await i.respond(choices.map(e=>({name:e,value:e})));return} if(i.isAutocomplete()){const focused=i.options.getFocused(true),query=String(focused.value??'').trim();if(['tournament','tournament-player','race','match-result','fixtures','tournament-report'].includes(i.commandName)&&focused.name==='tournament'){const rows=db.prepare("SELECT t.name,g.name game_name,t.status FROM tournaments t LEFT JOIN games g ON g.id=t.game_id WHERE t.name LIKE ? COLLATE NOCASE ORDER BY t.created_at DESC LIMIT 25").all(`%${query}%`) as any[];await i.respond(rows.map(t=>({name:`${t.name} • ${t.game_name||'General'} • ${t.status}`.slice(0,100),value:t.name})));return}if(['tournament-player','player-report','player-history','match-result'].includes(i.commandName)&&focused.name==='player'){const rows=db.prepare("SELECT name FROM players WHERE name LIKE ? COLLATE NOCASE ORDER BY name ASC LIMIT 25").all(`%${query}%`) as any[];await i.respond(rows.map(p=>({name:p.name,value:p.name})));return}if(['tournament','tournaments','player-report','player-history','game-report'].includes(i.commandName)&&focused.name==='game'){const rows=db.prepare("SELECT name FROM games WHERE name LIKE ? COLLATE NOCASE ORDER BY name ASC LIMIT 25").all(`%${query}%`) as any[];await i.respond(rows.map(g=>({name:g.name,value:g.name})));return}return}if(i.isChatInputCommand())await handleCommand(i);else if(i.isStringSelectMenu())await handleSelect(i);else if(i.isButton()){if(i.customId.startsWith('tgs:notification-role:'))await handleNotificationButton(i);else await handleButton(i);}else if(i.isModalSubmit()&&i.customId.startsWith('tgs:password:'))await handlePasswordModal(i);else if(i.isModalSubmit()&&i.customId.startsWith('tgs:update-form:'))await handleUpdateForm(i)}catch(e:any){console.error('Interaction error:',e);const msg='❌ Something went wrong while processing this action.';if(i.isRepliable()){if(i.replied||i.deferred)await i.followUp({content:msg,ephemeral:true}).catch(()=>{});else await i.reply({content:msg,ephemeral:true}).catch(()=>{})}}});registerCommands().catch(console.error);client.once('ready',()=>{console.log(`Logged in as ${client.user?.tag}`)});client.login(token!);
